modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.LowPass;
end Baseline;
model FINDING00862
  extends Modelica.Electrical.Analog.Examples.OpAmps.LowPass(f=0);
end FINDING00862;
model FINDING00863
  extends Modelica.Electrical.Analog.Examples.OpAmps.LowPass(fG=0);
end FINDING00863;
model FINDING00859
  extends Modelica.Electrical.Analog.Examples.OpAmps.LowPass(firstOrder(R2=0));
end FINDING00859;
model FinalFINDING00862
  extends Modelica.Electrical.Analog.Examples.OpAmps.LowPass(final f=0);
end FinalFINDING00862;
model FinalFINDING00863
  extends Modelica.Electrical.Analog.Examples.OpAmps.LowPass(final fG=0);
end FinalFINDING00863;
model FinalFINDING00859
  extends Modelica.Electrical.Analog.Examples.OpAmps.LowPass(firstOrder(final R2=0));
end FinalFINDING00859;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00862\n");
simulate(FINDING00862, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00863\n");
simulate(FINDING00863, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00859\n");
simulate(FINDING00859, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00862\n");
simulate(FinalFINDING00862, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00863\n");
simulate(FinalFINDING00863, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00859\n");
simulate(FinalFINDING00859, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE FINDING00862\n");
system("./Baseline -override f=0 -r=FINDING00862_override.csv");
print("AUDIT_OVERRIDE FINDING00863\n");
system("./Baseline -override fG=0 -r=FINDING00863_override.csv");
print("AUDIT_OVERRIDE FINDING00859\n");
system("./Baseline -override firstOrder.R2=0 -r=FINDING00859_override.csv");
